using System.Collections.Concurrent;
using System.IO;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using DesktopPet.Core.Animation;
using DesktopPet.Core.Traits;

namespace DesktopPet.App.SpriteSheet;

/// <summary>
/// The built-in art: one embedded sheet per character in <see cref="Characters.All"/> (the default characters from
/// <c>SpriteSheet/Fakemon/</c>, generated by <c>tools/sprites/make_character.py</c>, and the rabbit, <c>rabbit.png</c>,
/// generated by <c>tools/sprites/make_rabbit.py</c>). One row per animation in <see cref="Animations.All"/> order,
/// 64×64 cells, facing right, feet on the bottom row. Pixels are 0xAARRGGBB; the background is fully transparent so
/// clicks pass through. The rabbit wears each pet's own jacket colour (<see cref="JacketColors"/>); the other sheets
/// don't have its jacket colours, so recolouring leaves them as they are.
/// </summary>
internal static class DefaultArt
{
    public const int FrameSize = 64;

    private static readonly ConcurrentDictionary<string, (uint[] Pixels, int Width, int Height)> Sheets = new(StringComparer.OrdinalIgnoreCase);

    /// <summary>The character whose art stands for the app (the tray icon).</summary>
    public static string AppCharacter => Characters.Defaults[0].Id;

    /// <param name="character">A character id from <see cref="Characters.All"/>.</param>
    /// <param name="animationId">Animation.</param>
    /// <param name="frameIndex">Frame within it.</param>
    /// <param name="jacket">Jacket colours (<see cref="JacketColors"/>); null for the colours drawn in the sheet.</param>
    public static uint[] Frame(string character, string animationId, int frameIndex, JacketShades? jacket = null)
    {
        var row = IndexOf(animationId);
        var (sheet, width, _) = Sheets.GetOrAdd(character, LoadSheet);
        var px = new uint[FrameSize * FrameSize];
        for (var y = 0; y < FrameSize; y++)
        {
            Array.Copy(sheet, (((row * FrameSize) + y) * width) + (frameIndex * FrameSize), px, y * FrameSize, FrameSize);
        }

        return jacket is { } j ? Recolor(px, j) : px;
    }

    public static uint[] TrayIconPixels() => Frame(AppCharacter, Animations.Idle.Id, 0);

    /// <summary>The character's embedded sheet as PNG bytes, to write into a pet's sprites folder.</summary>
    public static byte[] SheetPng(string character)
    {
        using var stream = OpenSheet(character);
        using var copy = new MemoryStream();
        stream.CopyTo(copy);
        return copy.ToArray();
    }

    private static int IndexOf(string animationId)
    {
        for (var i = 0; i < Animations.All.Count; i++)
        {
            if (Animations.All[i].Id == animationId)
            {
                return i;
            }
        }

        throw new ArgumentException($"Unknown animation '{animationId}'.", nameof(animationId));
    }

    /// <summary>Swaps the rabbit's jacket colours, which appear nowhere else in the sheets, for <paramref name="jacket"/>.</summary>
    private static uint[] Recolor(uint[] px, JacketShades jacket)
    {
        var drawn = JacketColors.Variants[0];
        if (jacket == drawn)
        {
            return px;
        }

        for (var i = 0; i < px.Length; i++)
        {
            var c = px[i];
            px[i] = c == drawn.Base ? jacket.Base : c == drawn.Shade ? jacket.Shade : c == drawn.Light ? jacket.Light : c;
        }

        return px;
    }

    /// <summary>The embedded sheet: <c>DesktopPet.App.rabbit.png</c> or <c>DesktopPet.App.Characters.&lt;id&gt;.png</c> (any case).</summary>
    private static Stream OpenSheet(string character)
    {
        var assembly = typeof(DefaultArt).Assembly;
        var wanted = string.Equals(character, Characters.Rabbit, StringComparison.OrdinalIgnoreCase)
            ? "DesktopPet.App.rabbit.png"
            : $"DesktopPet.App.Characters.{character}.png";
        var name = assembly.GetManifestResourceNames().FirstOrDefault(n => string.Equals(n, wanted, StringComparison.OrdinalIgnoreCase));
        return (name is null ? null : assembly.GetManifestResourceStream(name))
            ?? throw new InvalidOperationException($"The built-in sprite sheet for '{character}' is missing from the assembly.");
    }

    private static (uint[] Pixels, int Width, int Height) LoadSheet(string character)
    {
        using var stream = OpenSheet(character);
        var decoder = new PngBitmapDecoder(stream, BitmapCreateOptions.PreservePixelFormat, BitmapCacheOption.OnLoad);
        var bitmap = new FormatConvertedBitmap(decoder.Frames[0], PixelFormats.Bgra32, null, 0);
        var (width, height) = (bitmap.PixelWidth, bitmap.PixelHeight);

        var columns = Animations.All.Max(a => a.FrameCount);
        if (width < columns * FrameSize || height < Animations.All.Count * FrameSize)
        {
            throw new InvalidDataException($"The '{character}' sheet is {width}×{height}; it needs a row of {FrameSize} px cells per animation.");
        }

        // Bgra32 bytes == 0xAARRGGBB little-endian. Straight (not premultiplied) alpha, like the old procedural art.
        var pixels = new uint[width * height];
        bitmap.CopyPixels(pixels, width * sizeof(uint), 0);
        return (pixels, width, height);
    }
}
